<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { LoaderCircle, Save } from "lucide-vue-next";
import { useRoute } from "vue-router";
import { operationsRepository } from "@/data/repositories/operationsRepository";

const route = useRoute(); const loading = ref(true); const saving = ref(false); const saved = ref(false); const error = ref("");
const form = reactive({ name: "", slug: "", code: "", status: "active", billing_email: "", city: "", country_code: "", timezone: "UTC", settings: {} });
const instituteId = () => Number(route.params.instituteId);
async function load() { loading.value = true; try { const page = await operationsRepository.institutes({ per_page: 100 }); const item = page.items.find((value) => value.id === instituteId()); if (!item) throw new Error("Institute not found."); Object.assign(form, { name: item.name, slug: item.slug, code: item.code, status: item.status, billing_email: item.billingEmail, city: item.city, country_code: item.countryCode, timezone: item.timezone, settings: item.settings }); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load institute."; } finally { loading.value = false; } }
async function save() { saving.value = true; saved.value = false; error.value = ""; try { await operationsRepository.update("institutes", instituteId(), form); saved.value = true; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to save settings."; } finally { saving.value = false; } }
onMounted(load);
</script>

<template><div class="mx-auto max-w-3xl space-y-5"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-mint">Organisation profile</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Institute settings</h2><p class="mt-1 text-[13px] text-ink3">Update the identity used across members, students and billing.</p></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-sm" @submit.prevent="save"><div v-if="loading" class="grid gap-4 sm:grid-cols-2"><span v-for="item in 8" :key="item" class="h-16 animate-pulse rounded-xl bg-bg-soft" /><span class="sr-only">Loading institute…</span></div><template v-else><div class="grid gap-4 sm:grid-cols-2"><label class="text-[11px] font-semibold">Institute name<input v-model="form.name" required class="ops-input" /></label><label class="text-[11px] font-semibold">Billing email<input v-model="form.billing_email" type="email" class="ops-input" /></label><label class="text-[11px] font-semibold">Slug<input v-model="form.slug" required class="ops-input" /></label><label class="text-[11px] font-semibold">Code<input v-model="form.code" required class="ops-input uppercase" /></label><label class="text-[11px] font-semibold">City<input v-model="form.city" class="ops-input" /></label><label class="text-[11px] font-semibold">Country code<input v-model="form.country_code" maxlength="2" class="ops-input uppercase" /></label><label class="text-[11px] font-semibold">Timezone<input v-model="form.timezone" class="ops-input" /></label><label class="text-[11px] font-semibold">Status<select v-model="form.status" class="ops-input"><option value="pending">Pending</option><option value="active">Active</option><option value="suspended">Suspended</option><option value="closed">Closed</option></select></label></div><div class="mt-6 flex items-center justify-end gap-3 border-t border-border pt-5"><span v-if="saved" class="text-[12px] font-semibold text-mint">Changes saved</span><button :disabled="saving" class="ops-button-primary flex items-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" /><Save v-else :size="14" /> {{ saving ? 'Saving…' : 'Save settings' }}</button></div></template></form></div></template>
